#include <iostream>
using namespace std;

// Complete inline function definition before any call site
inline double cube(const double side) {
    return side * side * side;
}

int main() {
    const double side1 = 1.0;
    const double side2 = 2.3;
    const double side3 = 5.4;

    cout << "Volume with side " << side1 << " is " << cube(side1) << endl;
    cout << "Volume with side " << side2 << " is " << cube(side2) << endl;
    cout << "Volume with side " << side3 << " is " << cube(side3) << endl;

    return 0;
}

#include <iostream>
using namespace std;

// Mandatory prototypes enabling type-safe linkage
int squareByValue(int number);          // pass-by-value
void squareByReference(int &numberRef); // pass-by-reference

int main() {
    int x = 2;
    cout << "x = " << x << " before squareByValue" << endl;
    cout << "Value returned by squareByValue: " << squareByValue(x) << endl;
    cout << "x = " << x << " after squareByValue" << endl << endl;

    int z = 4;
    cout << "z = " << z << " before squareByReference" << endl;
    squareByReference(z);
    cout << "z = " << z << " after squareByReference" << endl;

    return 0;
}

int squareByValue(int number) {
    return number *= number; // caller argument remains untouched
}

void squareByReference(int &numberRef) {
    numberRef *= numberRef;  // modifies caller variable z directly
}
